function rewrite(sql: string, subject: Subject, policies: Policy[]): string {
  let out = sql;
  for (const p of policies) {
    if (p.table && p.tenantColumn)
      out = injectWhere(out, p.table, `${p.tenantColumn} = '${subject.tenant}'`);
    if (p.maskedColumns?.length)
      out = maskColumns(out, p.table, p.maskedColumns);
  }
  return out;
}
